from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from django.contrib.auth import get_user_model
from customers.models import ClientTenant

User = get_user_model()

class ProvisionTenantMemberView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request):
        tenant_slug = request.data.get('tenant_slug')
        target_email = request.data.get('email')

        try:
            tenant = ClientTenant.objects.get(slug=tenant_slug, user_links__user=request.user, user_links__is_admin=True)
        except ClientTenant.DoesNotExist:
            return Response({'error': 'Tenant not found or unauthorized'}, status=status.HTTP_404_NOT_FOUND)

        try:
            user = User.objects.get(email=target_email)
        except User.DoesNotExist:
            return Response({'error': 'User not found'}, status=status.HTTP_404_NOT_FOUND)

        tenant.add_user(user, is_superuser=False, is_staff=False)
        return Response({'status': 'user_provisioned', 'tenant': tenant_slug, 'email': target_email})
